def frac_of_raw(raw):
    sign, man, exp, _ = raw
    if man == 0:
        return Fraction(0)
    v = Fraction(man) * (Fraction(2) ** exp)
    return -v if sign else v

def entropy_interval(masses):
    """Exact-rational enclosure [lo, hi] of -sum p ln p."""
    total = mpmath.iv.mpf(0)
    for p in masses:
        q = mpmath.iv.mpf(p.numerator) / mpmath.iv.mpf(p.denominator)
        total += q * mpmath.iv.log(q)
    lo, hi = (frac_of_raw(r) for r in (-total)._mpi_)
    assert lo <= hi
    return lo, hi

def pushforward(a, b):
    acc = {}
    for x, y, num in W:
        k = a * x + b * y
        acc[k] = acc.get(k, 0) + num
    return [Fraction(n, DEN) for n in acc.values()]

def floor45(f):
    q = (f * 10 ** 45).numerator // (f * 10 ** 45).denominator
    s = str(q).rjust(46, "0")
    return s[:-45] + "." + s[-45:]

def main():
    mpmath.iv.dps = DPS
    assert len(W) == 95 and len({(x, y) for x, y, _ in W}) == 95
    assert all(n > 0 for _, _, n in W)
    assert sum(n for _, _, n in W) == DEN, "weights do not sum to exactly 1"

    nlo, nhi = entropy_interval(pushforward(1, -1))         # H(X-Y)
    slope_los, slope_his = [], []
    for a, b in ((1, 0), (0, 1), (1, 1), (1, 2)):           # H(X), H(Y), H(X+Y), H(X+2Y)
        lo, hi = entropy_interval(pushforward(a, b))
        slope_los.append(lo); slope_his.append(hi)

    rho_lo = nlo / max(slope_his)    # rigorous lower bound on C_3c
    rho_hi = nhi / max(slope_los)

    print("C_3c >=", floor45(rho_lo), "(45-digit floor truncation)")
    assert floor45(rho_lo) == EXPECT_45, "digits do not match the PR claim"
    assert rho_lo > TABLE_ROW > RECORD_PUBLISHED, "does not beat the record"
    assert rho_hi < PROVEN_UB, "violates the proven upper bound 7/4"
    print("beats table row 1.6747338950208249:  True")
    print("beats published record 1.67473389:   True")
    print("below proven upper bound 7/4:        True")
    print("OK: C_3c >= 1.6747338950208249 certified")

